    .rst        (rst),                  //  i: Asynchronous reset

    .dp_tx      (fe_ctrl.dp_tx),        //  o: USB Data+ output
    .dn_tx      (fe_ctrl.dn_tx),        //  o: USB Data- output
    .tx_oen     (fe_ctrl.tx_oen),       //  o: USB Data output enable

    .tx_data    (sie_bus.tx_data),      //  i: USB data to transmit
    .tx_valid   (sie_bus.tx_valid),     //  i: Data on tx_data bus is valid
    .tx_ready   (sie_bus.tx_ready),     //  o: SIE ready to load transmit data into holding registers
    .tx_active  (sie_bus.tx_active)     //  o: Transmit state machine is active (from SYNC sending start to EOP sending end)
);

// FIXME: fix pullup control
assign fe_ctrl.pu = 1'b1;

endmodule : usb_sie

left_context:
//==============================================================================
//  SIE interface signals
//
//------------------------------------------------------------------------------
// [usb20dev] 2018 Eden Synrez <esynr3z@gmail.com>
//==============================================================================

import usb_pkg::*;

interface usb_sie_if ();

logic             reset;        // USB line reset active

bus8_t            tx_data;      // USB data to transmit
logic             tx_valid;     // Data on tx_data bus is valid
logic             tx_ready;     // SIE ready to load transmit data into holding registers
logic             tx_active;    // Transmit state machine is active (from SYNC sending start to EOP sending end)

// Example of packet transmission
//                 .---------------------------------.
//  tx_valid       |                                 |
//            -----'                                 '-----------------------
//            ----. .--. .--------------. .----------------------------------
//   tx_data   xxx X B0 X  BYTE1         X  BYTE2
//            ----' '--' '--------------' '----------------------------------
//                    .-.              .-.       .-.
//  tx_ready          | |              | |       | |
//            --------' '--------------' '-------' '-------------------------
//                        .-----------------------------------------------.
// tx_active              |                                               |
//            ------------'                                               '--
//                          .-------. .-------. .-------. .-------. .---.
//    D+/D-   ----IDLE-----<  SYNC   X  BYTE0  X  BYTE1  X  BYTE2  X EOP >---
//                          '-------' '-------' '-------' '-------' '---'

bus8_t            rx_data;      // Received USB data
logic             rx_valid;     // rx_data bus has valid data
logic             rx_active;    // Receive state machine is active (from detecting SYNC to detecting EOP)
logic             rx_error;     // Receive error detection (bitstuff error)

// Example of packet reception
//                     .-------. .-------. .-------. .-------. .---.
//     D+/D-  --IDLE--<  SYNC   X  BYTE0  X  BYTE1  X  BYTE2  X EOP >--IDLE--
//                     '-------' '-------' '-------' '-------' '---'
//                               .-----------------------------------.
// rx_active                     |                                   |
//            -------------------'                                   '-------
//            ---------------------------. .-------. .-------. .-------------
//                          xxx           X  BYTE0  X  BYTE1  X  BYTE2
//   rx_data  ---------------------------' '-------' '-------' '-------------
//                                        .-.       .-.       .-.
//                                        | |       | |       | |
//  rx_valid  ----------------------------' '-------' '-------' '------------
//                                                      .-.
//                                                      | |
//  rx_error  ------------------------------------------' '------------------
//  NOTE: rx_error can be asserted in any time bitstuff error occured.
//        PE should ignore the whole packet after that.

// Serial Interface Engine side
modport sie (
    output reset,

    input  tx_data,
    input  tx_valid,
    output tx_ready,
    output tx_active,

    output rx_data,
    output rx_valid,
    output rx_active,

right_context:
);

// Protocol Engine side
modport pe (
    input  reset,

    output tx_data,
    output tx_valid,
    input  tx_ready,
    input  tx_active,

    input  rx_data,
    input  rx_valid,
    input  rx_active,
    input  rx_error
);

endinterface : usb_sie_if

left_context:
//==============================================================================
// SIE receive side:
//   - data recovery from line states
//   - NRZI decoder
//   - bit unstuffer
//   - receive FSM
//
//------------------------------------------------------------------------------
// [usb20dev] 2018 Eden Synrez <esynr3z@gmail.com>
//==============================================================================

import usb_pkg::*;

module usb_sie_rx (
    input  logic    clk,       // Clock
    input  logic    rst,       // Asynchronous reset

    // Frontend rx
    input  logic    dn_rx,     // USB Data- input
    input  logic    dp_rx,     // USB Data+ input

    // SIE rx
    input  logic    tx_active, // Transmit state machine is active
    output bus8_t   rx_data,   // USB data output bus
    output logic    rx_valid,  // rx_data bus has valid data
    output logic    rx_active, // Receive state machine is active
    output logic    rx_error,  // Receive error detection
    output logic    bus_reset  // Bus reset active
);

localparam LINE_STATE_HIST_LEN = 3;

//-----------------------------------------------------------------------------
// Line state recovery
//-----------------------------------------------------------------------------
// Double-flop synchronization for input data lines
logic [3:0]       line_pair_ff;
usb_line_state_t line_pair;
usb_line_state_t line_state_curr;
logic             line_trans;
logic             line_idle;
logic             detect_eop;

always_ff @(posedge clk)
begin
    if (rst)
        line_pair_ff <= {USB_LS_J, USB_LS_J};
    else
        line_pair_ff <= {line_pair_ff[1:0], dn_rx, dp_rx};
end

assign line_pair = usb_line_state_t'(line_pair_ff[3:2]);

// We dont use true diff pair, so we have to handle data transition moments
// and change line state one clock after transition.
// It is supposed, that transition period is shorter than sample clock period.

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        line_trans <= 1'b0;
    else if ((line_state_curr != line_pair) && !line_trans)
        line_trans <= 1'b1;
    else
        line_trans <= 1'b0;
end

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        line_state_curr <= USB_LS_J;
    else if (line_trans)
        line_state_curr <= line_pair;
end

// Generate valid signal in the middle of each bit
logic [1:0] line_phase_cnt;
logic       line_state_valid;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        line_phase_cnt <= '0;
    else if (line_trans)
        line_phase_cnt <= '0;
    else
        line_phase_cnt <= line_phase_cnt + 'b1;
end

assign line_state_valid = (line_phase_cnt == 'b1) ? 1'b1 : 1'b0;

// Push line states to the history buffer for NRZI decoding and EOP detection
usb_line_state_t [LINE_STATE_HIST_LEN-1:0] line_state_hist;

always_ff @(posedge clk or posedge rst)
begin
    for (int i = 0; i < LINE_STATE_HIST_LEN; i++) begin
        if (rst)
            line_state_hist[i] <= USB_LS_J;
        else if (line_state_valid && (i == 0)) begin
            line_state_hist[i] <= line_state_curr;
        end else if (line_state_valid) begin
            line_state_hist[i] <= line_state_hist[i-1];
        end
    end
end

assign detect_eop  = (line_state_hist == USB_EOP_PATTERN);

//-----------------------------------------------------------------------------
// NRZI decoder
//-----------------------------------------------------------------------------
logic dec_nrzi_bit;
logic dec_nrzi_valid;

always_comb
begin
    if ((line_state_hist[1] == USB_LS_J) &&
        (line_state_hist[0] == USB_LS_J)) begin
        dec_nrzi_bit   = 1'b1;
        dec_nrzi_valid = line_state_valid;
    end else if ((line_state_hist[1] == USB_LS_J) &&
                 (line_state_hist[0] == USB_LS_K)) begin
        dec_nrzi_bit   = 1'b0;
        dec_nrzi_valid = line_state_valid;
    end else if ((line_state_hist[1] == USB_LS_K) &&
                 (line_state_hist[0] == USB_LS_J)) begin
        dec_nrzi_bit   = 1'b0;
        dec_nrzi_valid = line_state_valid;
    end else if ((line_state_hist[1] == USB_LS_K) &&
                 (line_state_hist[0] == USB_LS_K)) begin
        dec_nrzi_bit   = 1'b1;
        dec_nrzi_valid = line_state_valid;
    end else begin
        dec_nrzi_bit   = 1'b0;
        dec_nrzi_valid = 1'b0;
    end
end

//-----------------------------------------------------------------------------
// Bit unstuffer
//-----------------------------------------------------------------------------
logic [USB_STUFF_BITS_N-1:0] unstuff_shift;
logic                        unstuff_event;
logic                        unstuff_error;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        unstuff_shift <= '0;
    else if (dec_nrzi_valid)
        unstuff_shift <= {unstuff_shift[USB_STUFF_BITS_N-2:0], dec_nrzi_bit};
end

assign unstuff_event = (unstuff_shift == '1);
assign unstuff_error = unstuff_event && (dec_nrzi_bit != 1'b0);

//-----------------------------------------------------------------------------
// Data bitstream control
//-----------------------------------------------------------------------------
logic  data_bit;
logic  data_bit_valid;
bus8_t data_shift;
logic  detect_sync;

assign data_bit = dec_nrzi_bit;
assign data_bit_valid = dec_nrzi_valid && (!unstuff_event || line_idle) && (!tx_active);

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        data_shift <= '1;
    else if (detect_eop)
        data_shift <= '1;
    else if (data_bit_valid)
        data_shift <= {data_bit, data_shift[7:1]};
end

// SYNC and Idle detection
assign detect_sync = (data_shift == USB_SYNC_VAL);

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        line_idle <= 1'b1;
    else if (detect_sync && line_idle)
        line_idle <= 1'b0;
    else if (detect_eop)
        line_idle <= 1'b1;
end

//-----------------------------------------------------------------------------
// Receive state machine
//-----------------------------------------------------------------------------
enum logic [2:0] {
    RX_WAIT_S,
    STRIP_SYNC_S,
    RX_DATA_S,
    STRIP_EOP_S,
    ERROR_S,
    ABORT_S,
    TERMINATE_S,
    XXX_S = 'x
} fsm_state, fsm_next;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        fsm_state <= RX_WAIT_S;
    else
        fsm_state <= fsm_next;
end

always_comb
begin
    fsm_next = XXX_S;
    case (fsm_state)
        RX_WAIT_S : begin
            if (detect_sync && (!tx_active))
                fsm_next = STRIP_SYNC_S;
            else
                fsm_next = RX_WAIT_S;
        end

        STRIP_SYNC_S : begin
            fsm_next = RX_DATA_S;
        end

        RX_DATA_S : begin
            if (unstuff_error)
                fsm_next = ERROR_S;
            else if (detect_eop)
                fsm_next = STRIP_EOP_S;
            else
                fsm_next = RX_DATA_S;
        end

        STRIP_EOP_S : begin
            fsm_next = RX_WAIT_S;
        end

        ERROR_S : begin
            fsm_next = ABORT_S;
        end

        ABORT_S : begin
            if (line_idle)
                fsm_next = TERMINATE_S;
            else
                fsm_next = ABORT_S;
        end

        TERMINATE_S : begin
            fsm_next = RX_WAIT_S;
        end
    endcase
end

logic  [3:0] data_bit_cnt;
bus8_t       data_hold;
logic        data_valid;
logic        data_active;
logic        data_error;

always_ff @(posedge clk or posedge rst)
begin
    if (rst) begin
        data_bit_cnt <= '0;
        data_hold    <= '0;
        data_valid   <= 1'b0;
        data_active  <= 1'b0;
        data_error   <= 1'b0;
    end else begin
        case (fsm_state)
            RX_WAIT_S : begin
                data_bit_cnt <= '0;
            end

            STRIP_SYNC_S : begin
                data_active <= 1'b1;
            end

            RX_DATA_S : begin
                // count shifted data bits
                if (data_bit_valid) begin
                    if (data_bit_cnt == 'd8)
                        data_bit_cnt <= 'd1;
                    else
                        data_bit_cnt <= data_bit_cnt + 1;
                end
                // hold data when byte accumulated
                if (data_bit_cnt == 'd8) begin
                    data_hold <= data_shift;
                    data_valid <= 1'b1;
                end else
                    data_valid <= 1'b0;
            end

right_context:
            ERROR_S : begin
                data_error  = 1'b1;
            end

            ABORT_S : begin
                data_valid  = 1'b0;
                data_error  = 1'b0;
            end

            TERMINATE_S : begin
                data_active = 1'b0;
            end
        endcase
    end
end

// Data valid should be a pulse for FS
logic data_valid_ff;
logic data_valid_pulse;

always_ff @(posedge clk or posedge rst)
begin
    if (rst) begin
        data_valid_ff <= 1'b0;
    end else begin
        data_valid_ff <= data_valid;
    end
end

assign data_valid_pulse = data_valid && (!data_valid_ff);

//-----------------------------------------------------------------------------
// Bus reset detection
//-----------------------------------------------------------------------------
logic line_reset;
bus8_t line_reset_cnt;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        line_reset_cnt <= '0;
    else if (!line_reset && (line_state_hist[0] == USB_LS_SE0))
        line_reset_cnt <= line_reset_cnt + 'b1;
    else
        line_reset_cnt <= '0;
end

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        line_reset <= 1'b0;
    else if (!line_reset && (line_reset_cnt == '1))
        line_reset <= 1'b1;
    else if (line_reset && (line_state_hist[0] != USB_LS_SE0))
        line_reset <= 1'b0;
end

//-----------------------------------------------------------------------------
// Outputs registering stage
//-----------------------------------------------------------------------------
always_ff @(posedge clk or posedge rst)
begin
    if (rst) begin
        rx_data    <= '0;
        rx_valid   <= 1'b0;
        rx_active  <= 1'b0;
        rx_error   <= 1'b0;
        bus_reset  <= 1'b0;
    end else begin
        rx_data    <= data_hold;
        rx_valid   <= data_valid_pulse;
        rx_active  <= data_active;
        rx_error   <= data_error;
        bus_reset  <= line_reset;
    end
end

endmodule : usb_sie_rx

left_context:
//==============================================================================
// SIE transmit side:
//   - NRZI encoder
//   - bit stuffer
//   - data to line states convert
//   - transmit FSM
//
//------------------------------------------------------------------------------
// [usb20dev] 2018 Eden Synrez <esynr3z@gmail.com>
//==============================================================================

import usb_pkg::*;

module usb_sie_tx (
    input  logic    clk,        // Clock
    input  logic    rst,        // Asynchronous reset

    // Frontend tx
    output logic    dp_tx,      // USB Data+ output
    output logic    dn_tx,      // USB Data- output
    output logic    tx_oen,     // USB Data output enable

    // SIE tx
    input  bus8_t   tx_data,    // USB data input bus
    input  logic    tx_valid,   // Transmit data on tx_data bus is valid
    output logic    tx_ready,   // UTM ready to load transmit data into holding registers
    output logic    tx_active   // Transmit state machine is active (from SYNC sending start to EOP sending end)
);

//-----------------------------------------------------------------------------
// Transmit state machine
//-----------------------------------------------------------------------------
logic data_hold_full;
logic data_oen;
logic data_se0;

enum logic [2:0] {
    TX_WAIT_S,
    SEND_SYNC_S,
    TX_DATA_LOAD_S,

right_context:
always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        fsm_state <= TX_WAIT_S;
    else
        fsm_state <= fsm_next;
end

always_comb
begin
    fsm_next = XXX_S;
    case (fsm_state)
        TX_WAIT_S : begin
            if (tx_valid)
                fsm_next = SEND_SYNC_S;
            else
                fsm_next = TX_WAIT_S;
        end

        SEND_SYNC_S : begin
            fsm_next = TX_DATA_LOAD_S;
        end

        TX_DATA_LOAD_S : begin
            if ((!tx_valid) && (!data_oen))
                fsm_next = TX_WAIT_S;
            else
                fsm_next = TX_DATA_WAIT_S;
        end

        TX_DATA_WAIT_S : begin
            if (!data_hold_full)
                fsm_next = TX_DATA_LOAD_S;
            else
                fsm_next = TX_DATA_WAIT_S;
        end
    endcase
end

logic        data_shift_last;
logic  [3:0] data_bit_cnt;
bus8_t       data_hold;
bus8_t       data_shift;
logic        data_bit_strobe;
logic        stuff_event;

always_ff @(posedge clk or posedge rst)
begin
    if (rst) begin
        data_bit_cnt    <= '0;
        data_hold       <= '0;
        data_shift      <= '0;
        data_oen        <= 1'b0;
        data_shift_last <= 1'b0;
        data_hold_full  <= 1'b0;
        tx_ready        <= 1'b0;
        data_se0        <= 1'b0;
    end else begin
        case (fsm_state)
            TX_WAIT_S : begin
                data_bit_cnt    <= 'd0;
                data_shift_last <= 1'b0;
            end

            SEND_SYNC_S : begin
                data_shift <= USB_SYNC_VAL;
            end

            TX_DATA_LOAD_S : begin
                if (tx_valid) begin
                    data_hold      <= tx_data;
                    data_hold_full <= 1'b1;
                    tx_ready       <= 1'b1;
                end else if (!tx_valid && data_oen) begin
                    data_hold       <= 'd0;
                    data_hold_full  <= 1'b1;
                    tx_ready        <= 1'b0;
                    data_shift_last <= 1'b1;
                end
            end

            TX_DATA_WAIT_S : begin
                tx_ready <= 1'b0;

                // data shifting on every strobe
                if (data_bit_strobe) begin
                    data_shift   <= data_shift >> 1;
                    data_bit_cnt <= data_bit_cnt + 1;
                    if (data_se0 && (data_bit_cnt == 'd12))
                        data_hold_full <= 1'b0;
                end else if (data_bit_cnt == 'd8) begin
                    data_shift     <= data_hold;
                    data_hold_full <= 1'b0;
                    if (!data_shift_last)
                        data_bit_cnt   <= 'd0;
                end

                // data output enable should be active till last se0 of eop have been transmitted
                if (data_bit_strobe)
                    data_oen <= (data_se0 && (data_bit_cnt == 'd12)) ? 1'b0 : 1'b1;

                // signalling that last bit of last byte transmitted and next will be se0 of eop
                if ((data_bit_cnt == 'd10) && data_shift_last && (!stuff_event)) begin
                    data_se0 <= 1'b1;
                end else if (data_bit_strobe && data_se0 && (data_bit_cnt == 'd12)) begin
                    data_se0 <= 1'b0;
                end
            end
        endcase
    end
end

logic       data_bit;
logic [1:0] data_bit_phase_cnt;
logic       data_bit_valid;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        data_bit_phase_cnt <= '1;
    else if (!data_oen)
        data_bit_phase_cnt <= '1;
    else
        data_bit_phase_cnt <= data_bit_phase_cnt + 'b1;
end

assign data_bit_valid = (data_bit_phase_cnt == '1);

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        data_bit <= 1'b0;
    else if (!data_oen)
        data_bit <= 1'b0;
    else if (data_bit_strobe)
        data_bit <= data_shift[0];
end

assign data_bit_strobe = data_bit_valid && (!stuff_event);

//-----------------------------------------------------------------------------
// Bit stuffer
//-----------------------------------------------------------------------------
logic [USB_STUFF_BITS_N-1:0] stuff_shift;
logic                        stuff_bit;
logic                        stuff_bit_valid;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        stuff_shift <= '0;
    else if (data_bit_valid)
        stuff_shift <= {stuff_shift[USB_STUFF_BITS_N-2:0], stuff_event? 1'b0 : data_bit};
end

assign stuff_event     = (stuff_shift == '1);

always_ff @(posedge clk or posedge rst)
begin
    if (rst) begin
        stuff_bit       <= 1'b0;
        stuff_bit_valid <= 1'b0;
    end else if (!data_oen) begin
        stuff_bit       <= 1'b0;
        stuff_bit_valid <= 1'b0;
    end else begin
        stuff_bit       <= stuff_event? 1'b0 : data_bit;
        stuff_bit_valid <= data_bit_valid;
    end
end

//-----------------------------------------------------------------------------
// NRZI encoder
//-----------------------------------------------------------------------------
logic enc_nrzi_bit;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        enc_nrzi_bit <= 1'b1;
    else if (!data_oen)
        enc_nrzi_bit <= 1'b1;
    else if (stuff_bit_valid && (stuff_bit == 1'b0))
        enc_nrzi_bit <= ~enc_nrzi_bit;
end

//-----------------------------------------------------------------------------
// Data to line states converter
//-----------------------------------------------------------------------------
always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        {dn_tx, dp_tx} <= USB_LS_J;
    else if (!data_oen)
        {dn_tx, dp_tx} <= USB_LS_J;
    else if (stuff_bit_valid && data_se0)
        {dn_tx, dp_tx} <= USB_LS_SE0;
    else if (stuff_bit_valid)
        {dn_tx, dp_tx} <= {!enc_nrzi_bit, enc_nrzi_bit};
end

// Output enable expander - to drive J one bit time after EOP transmitted
logic [3:0] data_oen_ff;

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        data_oen_ff <= '0;
    else
        data_oen_ff <= {data_oen_ff[2:0], data_oen};
end

always_ff @(posedge clk or posedge rst)
begin
    if (rst)
        tx_oen <= 1'b0;
    else
        tx_oen <= |data_oen_ff;
end

assign tx_active = tx_oen;

endmodule : usb_sie_tx

localparam USB_RAW_BITS  = USB_RAW_BYTES*8;

//-----------------------------------------------------------------------------
// Connections
//-----------------------------------------------------------------------------
logic dp_tx, dn_tx;
wire  dp_rx, dn_rx;

pullup  (phy.dp);
pulldown(phy.dn);

assign phy.dp = dp_tx;
assign phy.dn = dn_tx;
assign dp_rx = phy.dp;
assign dn_rx = phy.dn;

initial
begin
    send_raw_nondrive();
end

//-----------------------------------------------------------------------------
// Raw line control tasks
//-----------------------------------------------------------------------------
task wait_interpacket_delay;
begin
    #`USB_PERIOD_DEL;
    #`USB_PERIOD_DEL;
    #`USB_PERIOD_DEL;
    #`USB_PERIOD_DEL;
    #`USB_PERIOD_DEL;
    #`USB_PERIOD_DEL;
end
endtask : wait_interpacket_delay

task send_raw_bit(
    input logic dp,
    input logic dn
);
bit jit_sel;
begin
    jit_sel = $urandom_range(0,1);

    if (jit_sel) begin
        dp_tx <= dp;
        #`USB_PHASE_DEL dn_tx <= dn;
    end else begin
        dn_tx <= dn;
        #`USB_PHASE_DEL dp_tx <= dp;
    end

    #`USB_PERIOD_DEL;
end
endtask : send_raw_bit

task send_raw_nondrive;
begin
    send_raw_bit(1'bz, 1'bz);
end
endtask : send_raw_nondrive

task send_raw_k;
begin
      send_raw_bit(0, 1);
end
endtask : send_raw_k

task send_raw_j;
begin
      send_raw_bit(1, 0);
end
endtask : send_raw_j

task send_raw_se0;
begin
      send_raw_bit(0, 0);
end
endtask : send_raw_se0

task send_raw_packet(
    input logic [USB_RAW_BITS-1:0] data,
    input int len
);
bit enc_nrzi_bit;
int stuff_bit_cnt;
begin
    //Sync
    send_raw_k();
    send_raw_j();
    send_raw_k();
    send_raw_j();
    send_raw_k();
    send_raw_j();
    send_raw_k();
    send_raw_k();

    enc_nrzi_bit = 0;
    stuff_bit_cnt = 1;

    for (int i = 0; i < len*8; i++) begin
        // NRZI encoding
        if (!data[i])
            enc_nrzi_bit = !enc_nrzi_bit;
        send_raw_bit(enc_nrzi_bit, !enc_nrzi_bit);

        // Bit stuffing
        if (data[i])
            stuff_bit_cnt++;
        else
            stuff_bit_cnt = 0;

        if (stuff_bit_cnt >= USB_STUFF_BITS_N) begin
            stuff_bit_cnt = 0;
            enc_nrzi_bit = !enc_nrzi_bit;
            send_raw_bit(enc_nrzi_bit, !enc_nrzi_bit);
        end
    end

    // EOP
    send_raw_se0();
    send_raw_se0();
    send_raw_j();
    send_raw_nondrive();
    wait_interpacket_delay();
end
endtask : send_raw_packet

task receive_raw_packet (
    output logic [USB_RAW_BITS-1:0] data,
    output int len
);
usb_line_state_t [7:0]   line_state_hist;
int                      unstuff_cnt;
int                      bit_cnt;
logic [USB_RAW_BITS-1:0] bit_data;
begin
    bit_cnt = 0;
    bit_data = '0;
    line_state_hist = {8{USB_LS_J}};

    // wait for sync pattern
    while (line_state_hist != USB_SYNC_PATTERN) begin
        line_state_hist = {line_state_hist[6:0], usb_line_state_t'({dn_rx, dp_rx})};
        #`USB_PERIOD_DEL;
    end

    unstuff_cnt = 1; // SYNC has 1 in the end

    // get data
    while (line_state_hist[2:0] != USB_EOP_PATTERN) begin
        line_state_hist = {line_state_hist[6:0], usb_line_state_t'({dn_rx, dp_rx})};

        if (line_state_hist[2:0] == USB_EOP_PATTERN) begin
            if (line_state_hist[3] == USB_LS_SE0)
                $display("%0d, W: %m: Warning, EOP must have 2 se0 bits!", $time);
            break;
        end
        else if (line_state_hist[0] == USB_LS_SE0) begin
            //continue;
        end else if (unstuff_cnt == USB_STUFF_BITS_N) begin
            if (line_state_hist[0] == line_state_hist[1])
                $display("%0d, W: %m: Warning, should be '0' after 6 '1's!", $time);
            unstuff_cnt = 0;
        end else begin // regular data bit
            bit_cnt = bit_cnt + 1;
            // NRZI decoding and bit stuffing control
            if (line_state_hist[0] == line_state_hist[1]) begin
                bit_data = {1'b1, bit_data[USB_RAW_BITS-1:1]};
                unstuff_cnt = unstuff_cnt + 1;
            end else begin
                bit_data = {1'b0, bit_data[USB_RAW_BITS-1:1]};
                unstuff_cnt = 0;
            end
        end

        #`USB_PERIOD_DEL;
    end

    // shift lsb to the array bottom
    bit_data = bit_data >> (USB_RAW_BITS - bit_cnt);

    data = bit_data;
    len  = bit_cnt/8;
    if (bit_cnt%8 != 0)
        $display("%0d, W: %m: Warning, number of bits is not multiple of 8!", $time);

    wait_interpacket_delay();
end
endtask : receive_raw_packet

task send_reset;
begin
    send_raw_se0();
    #10ms;
    send_raw_j();
    send_raw_nondrive();
end
endtask : send_reset

logic [4:0]  crc5 = '1;
task step_crc5(
    input  [7:0] dbyte,
    output [4:0] crc_o
);
const bit [4:0] crc5_poly = 5'b00101;
begin
    for (int i = 0; i < 8; i++)
    begin
        if (crc5[4] ^ dbyte[i])
            crc5 = (crc5 << 1) ^ crc5_poly;
        else
            crc5 = crc5 << 1;
    end
    crc_o = crc5;
end
endtask : step_crc5

task valid_crc5(
    input [4:0] crc5,
    output      valid
);
const bit [4:0] crc5_res  = USB_CRC5_VALID;
begin
    valid = (crc5_res == crc5);
end
endtask : valid_crc5

logic [15:0]  crc16 = '1;
task step_crc16(
    input  [7:0] dbyte,
    output [15:0] crc_o
);
const bit [15:0] crc16_poly = 16'b1000000000000101;
begin
    for (int i = 0; i < 8; i++)
    begin
        if (crc16[15] ^ dbyte[i])
            crc16 = (crc16 << 1) ^ crc16_poly;
        else
            crc16 = crc16 << 1;
    end
    crc_o = crc16;
end
endtask : step_crc16

task valid_crc16(
    input [15:0] crc16,
    output      valid
);
const bit [15:0] crc16_res = USB_CRC16_VALID;
begin
    valid = (crc16_res == crc16);
end
endtask : valid_crc16

